  const allRows = $input.all().map(i => i.json);

  const now = DateTime.now().setZone('America/Montevideo');

  // Filtrar al mes corriente
  const currentMonth = now.setLocale('es').toFormat('MMMM').toLowerCase();
  const rows = allRows.filter(r =>
    String(r.Mes || '').trim().toLowerCase() === currentMonth
  );

  // Computar máximo Semana válido para el mes corriente
  const mStart = now.startOf('month');
  const lastDay = now.endOf('month').day;
  const daysToFirstSun = (7 - mStart.weekday) % 7;
  const firstMondayDay = daysToFirstSun + 2;
  const maxWeek = (lastDay < firstMondayDay) ? 1 : 2 + Math.floor((lastDay - firstMondayDay) / 7);

  const normalizeKey = (s) =>
    String(s ?? '').trim()
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
      .replace(/[^\w]+/g, '_')
      .replace(/^_+|_+$/g, '')
      .replace(/_+/g, '_')
      .toUpperCase();

  const toNumber = (v) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : 0;
  };

  const groups = new Map();

  for (const r of rows) {
    // Descartar semanas fuera de rango
    const weekNum = parseInt(String(r.Semana_mes).replace(/\D/g, ''));
    if (weekNum > maxWeek) continue;

    const semana_mes = r.Semana_mes;
    const sucursal = r.Sucursal;
    const key = `${semana_mes}||${sucursal}`;

    if (!groups.has(key)) {
      groups.set(key, {
        Semana_mes: semana_mes,
        Sucursal: sucursal,
        sum_Abono_Libre: toNumber(r.sum_Abono_Libre ?? 0),
      });
    } else {
      groups.get(key).sum_Abono_Libre += toNumber(r.sum_Abono_Libre ?? 0);
    }

    const g = groups.get(key);
    const catKey = `sum_${normalizeKey(r.Categoria)}`;
    g[catKey] = (g[catKey] ?? 0) + toNumber(r.sum_Pagado_Prestación ?? 0);
  }

  return Array.from(groups.values()).map(obj => ({ json: obj }));
}

